```{.r .cell-code}
# Transform data
SR_rils  <- SR_rils                          |> 
  mutate(log_visits = log(.2 + mean_visits))

# Compare variance
SR_rils                                      |> 
  group_by(petal_color)                      |>
  summarise(var_visits = var(log_visits))
```
